async function main(req) {
  const body = jsonParse(req.body, {});
  const action = body.action || 'help';
  const input = body.input || '';

  switch (action) {
    case 'sha256':
      return { hash: await sha256(input), algorithm: 'sha256' };

    case 'md5':
      return { hash: await md5(input), algorithm: 'md5' };

    case 'base64_encode':
      return { result: btoa(input), encoding: 'base64' };

    case 'base64_decode':
      try {
        return { result: atob(input), encoding: 'utf8' };
      } catch (_) {
        return { error: 'invalid base64 input' };
      }

    case 'url_encode':
      return { result: urlEncode(input) };

    case 'url_decode':
      return { result: urlDecode(input) };

    case 'uuid':
      return { uuid: uuid() };

    case 'uuid_bulk': {
      const count = Math.min(parseInt(body.count) || 5, 100);
      return { uuids: Array.from({ length: count }, () => uuid()) };
    }

    case 'timestamp':
      return {
        unix: Math.floor(Date.now() / 1000),
        unix_ms: Date.now(),
        iso: new Date().toISOString(),
        utc: new Date().toUTCString()
      };

    case 'random': {
      const len = Math.min(parseInt(body.length) || 32, 256);
      const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
      let result = '';
      for (let i = 0; i < len; i++) result += chars[Math.floor(Math.random() * chars.length)];
      return { random: result, length: len };
    }

    default:
      return {
        actions: ['sha256', 'md5', 'base64_encode', 'base64_decode', 'url_encode', 'url_decode', 'uuid', 'uuid_bulk', 'timestamp', 'random'],
        usage: { action: 'sha256', input: 'hello world' }
      };
  }
}
